INSERT INTO "enquiries" ("id", "customer_name", "phone", "email", "college_name", "subject", "message", "status", "follow_up_date", "internal_notes", "created_at") VALUES ('enq_002', 'Vigneshwaran', '+91 97777 22222', 'vignesh.vit@vitstudent.ac.in', 'VIT Vellore', 'Sample T-shirt print quality check', 'Can you send a sample physical printed shirt or fabric swatch to our college address before we place 75 shirts order?', 'contacted', '2026-11-11', 'Dispatched sample swatch kit via DTDC on 9th Nov.', '2026-11-10T09:56:56.884Z') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "customer_name", "college_name", "rating", "comment", "order_id", "is_approved", "is_published_testimonial", "created_at") VALUES ('rev_001', 'Antony Joseph', 'Loyola College, Chennai', 5, 'The print clarity on every single classmate face in the Honeycomb layout was stunning! The fabric markers did not bleed at all on Signature Day. Everyone in our batch cherishes the shirts!', 'JK-2026-0004', 1, 1, '2026-11-10T09:56:56.884Z') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "customer_name", "college_name", "rating", "comment", "order_id", "is_approved", "is_published_testimonial", "created_at") VALUES ('rev_002', 'Rohan Kulkarni', 'IIT Bombay', 5, 'Super fast turnaround! The personalized wooden photo frame included in the Top Pack was the highlight of our farewell. Highly recommend JK Empress for any college batch.', 'JK-2026-0002', 1, 1, '2026-11-10T09:56:56.884Z') ON CONFLICT DO NOTHING;
